import com.bridger.momentum.*;
import java.nio.file.*;
import javax.sound.sampled.*;
public final class ClipMicrophoneRegression {
 private static void jitter()throws Exception{ClipPcmBuffer ring=new ClipPcmBuffer(48000);byte[] original=new byte[96000];for(int i=0;i<48000;i++){short sample=(short)(Math.sin(i*2*Math.PI*700/48000)*12000);original[2*i]=(byte)sample;original[2*i+1]=(byte)(sample>>8);}long first=10000000000L;for(int packet=0;packet<50;packet++){byte[] data=java.util.Arrays.copyOfRange(original,packet*1920,(packet+1)*1920);long jitter=packet==0?0:(packet%2==0?8000000L:-6000000L);ring.add(first+(packet+1)*20000000L+jitter,data,data.length);}if(!java.util.Arrays.equals(original,ring.snapshot(first,first+1000000000L)))throw new AssertionError("Scheduling jitter corrupted contiguous microphone samples");}
 public static void main(String[] args)throws Exception{jitter();ClipPcmBuffer buffer=new ClipPcmBuffer(48000);byte[] tone=new byte[96000];for(int i=0;i<48000;i++){short value=(short)(Math.sin(i*2*Math.PI*440/48000)*12000);tone[2*i]=(byte)value;tone[2*i+1]=(byte)(value>>8);}long start=10000000000L;buffer.add(start+1000000000L,tone,tone.length);byte[] pcm=buffer.snapshot(start,start+1000000000L);if(pcm.length!=96000||pcm[100]!=tone[100])throw new AssertionError("Timestamped PCM changed");byte[] half=buffer.snapshot(start+500000000L,start+1000000000L);if(half.length!=48000||half[101]!=tone[48101])throw new AssertionError("Microphone interval trim is inaccurate");Path wave=Files.createTempDirectory("mic-test-").resolve("mic.wav");buffer.wave(start,start+1000000000L,wave);try(AudioInputStream audio=AudioSystem.getAudioInputStream(wave.toFile())){if(audio.getFrameLength()!=48000||audio.getFormat().getChannels()!=1||audio.getFormat().getSampleSizeInBits()!=16)throw new AssertionError("Invalid microphone WAV");}buffer.clear();try{buffer.snapshot(start,start+1000000000L);throw new AssertionError("Empty microphone invented audio");}catch(java.io.IOException expected){}for(int i=0;i<100;i++)buffer.add(start+i*1000000000L,tone,tone.length);try{buffer.snapshot(start,start+1000000000L);throw new AssertionError("Old microphone data retained past buffer window");}catch(java.io.IOException expected){}if(!ClipMicrophone.status().equals("Microphone off"))throw new AssertionError("Microphone active without opt in");System.out.println("PASS: bounded microphone PCM timeline, exact interval trimming, valid WAV and no device opened by default");}
}
